<script lang="ts">
	import type { ActionData, PageData } from './$types';
	import { formatDateTime, translate } from '#lib/i18n.js';
	let { data, form }: { data: PageData; form: ActionData } = $props();
	const t = (key: string) => translate(data.locale, key);
	const canInvite = $derived(data.role === 'owner' || data.role === 'admin');
</script>

<svelte:head><title>{t('members.title')} · mcproxy</title></svelte:head>
<main class="min-h-screen bg-slate-950 text-slate-200">
	<div class="mx-auto max-w-5xl px-6 py-8 lg:px-10">
		<header class="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold uppercase tracking-[0.25em] text-cyan-400">mcproxy</p><h1 class="mt-2 text-3xl font-bold text-white">{t('members.title')}</h1><p class="mt-2 text-slate-400">{t('members.help')}</p></div><a href="/" class="rounded-lg border border-slate-700 px-4 py-2 text-sm hover:border-cyan-400">{t('members.back')}</a></header>
		{#if form?.error}<div role="alert" aria-live="assertive" class="mb-5 rounded-xl border border-red-500/30 bg-red-500/10 p-4 text-sm text-red-300">{form.error}</div>{/if}
		{#if form?.success}<div role="status" aria-live="polite" class="mb-5 rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4 text-sm text-emerald-300"><p>{form.success}</p>{#if form.inviteURL}<code class="mt-2 block break-all text-xs">{form.inviteURL}</code><p class="mt-2 text-xs">{t('members.copyInvite')}</p>{/if}{#if form.temporaryPassword}<p class="mt-2">{t('members.temporary')}: <code class="font-mono">{form.temporaryPassword}</code></p>{/if}</div>{/if}
		{#if canInvite}<form method="POST" action="?/createInvitation" class="mb-8 grid gap-3 rounded-xl border border-slate-800 bg-slate-900/80 p-5 md:grid-cols-4"><input name="username" required aria-label={t('members.username')} placeholder={t('members.username')} class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" /><select name="role" aria-label={t('members.role')} class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white"><option value="viewer">{t('members.viewer')}</option><option value="auditor">{t('members.auditor')}</option><option value="operator">{t('members.operator')}</option><option value="admin">{t('members.admin')}</option>{#if data.role === 'owner'}<option value="owner">{t('members.owner')}</option>{/if}</select><input name="server_scope" aria-label={t('members.scope')} placeholder={t('members.scope')} class="rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" /><button class="rounded-lg bg-cyan-400 px-4 py-2 text-sm font-semibold text-slate-950 hover:bg-cyan-300">{t('members.invite')}</button></form>{/if}
		<section class="mb-8 rounded-xl border border-slate-800 bg-slate-900/80"><h2 class="border-b border-slate-800 px-5 py-4 font-semibold text-white">{t('members.members')}</h2><div class="divide-y divide-slate-800">{#each data.members as member}<div class="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><p class="font-medium text-white">{member.username} <span class={member.active ? 'text-emerald-400' : 'text-slate-500'}>({member.active ? t('members.active') : t('members.inactive')})</span></p><p class="text-xs text-slate-500">{member.serverScope.length ? `${t('members.scope')}: ${member.serverScope.join(', ')}` : t('members.allServers')}</p></div><div class="flex flex-wrap items-center justify-end gap-3"><span class="rounded-full bg-cyan-400/10 px-3 py-1 text-xs text-cyan-300">{member.role === 'viewer' ? t('members.viewer') : member.role === 'auditor' ? t('members.auditor') : member.role === 'operator' ? t('members.operator') : member.role === 'admin' ? t('members.admin') : t('members.owner')}</span>{#if canInvite && member.id !== data.currentUserId}<form method="POST" action="?/updateMember" class="flex flex-wrap items-center gap-2"><input type="hidden" name="user_id" value={member.id} /><select name="role" aria-label={`${member.username} ${t('members.role')}`} class="rounded border border-slate-700 bg-slate-950 px-2 py-1 text-xs text-white"><option value="viewer" selected={member.role === 'viewer'}>{t('members.viewer')}</option><option value="auditor" selected={member.role === 'auditor'}>{t('members.auditor')}</option><option value="operator" selected={member.role === 'operator'}>{t('members.operator')}</option><option value="admin" selected={member.role === 'admin'}>{t('members.admin')}</option>{#if data.role === 'owner'}<option value="owner" selected={member.role === 'owner'}>{t('members.owner')}</option>{/if}</select><input name="server_scope" value={member.serverScope.join(', ')} aria-label={`${member.username} ${t('members.scope')}`} class="w-28 rounded border border-slate-700 bg-slate-950 px-2 py-1 text-xs text-white" /><button class="rounded border border-cyan-500/50 px-2 py-1 text-xs text-cyan-300">{t('members.save')}</button></form>{#if member.active}<form method="POST" action="?/resetPassword" onsubmit={(event) => { if (!confirm(t('members.resetConfirm'))) event.preventDefault(); }}><input type="hidden" name="user_id" value={member.id} /><button class="rounded border border-amber-500/50 px-2 py-1 text-xs text-amber-200 hover:bg-amber-400/10">{t('members.reset')}</button></form><form method="POST" action="?/resetMFA" onsubmit={(event) => { if (!confirm(t('members.mfaResetConfirm'))) event.preventDefault(); }}><input type="hidden" name="user_id" value={member.id} /><button class="rounded border border-red-500/50 px-2 py-1 text-xs text-red-200 hover:bg-red-400/10">{t('members.resetMFA')}</button></form>{/if}<form method="POST" action="?/setActive" onsubmit={(event) => { if (member.active && !confirm(t('members.deactivateConfirm'))) event.preventDefault(); }}><input type="hidden" name="user_id" value={member.id} /><input type="hidden" name="active" value={String(!member.active)} /><button class="rounded border border-slate-700 px-2 py-1 text-xs text-slate-300">{member.active ? t('members.deactivate') : t('members.activate')}</button></form>{/if}</div></div>{:else}<p class="p-5 text-sm text-slate-500">{t('members.empty')}</p>{/each}</div></section>
		<section class="rounded-xl border border-slate-800 bg-slate-900/80"><h2 class="border-b border-slate-800 px-5 py-4 font-semibold text-white">{t('members.invitations')}</h2><div class="divide-y divide-slate-800">{#each data.invitations as invitation}<div class="flex flex-wrap items-center justify-between gap-3 px-5 py-4 text-sm"><div><p class="text-white">{invitation.username} · {invitation.role}</p><p class="text-xs text-slate-500">{invitation.expiresAt}</p></div><span class={invitation.usedAt ? 'text-slate-500' : 'text-amber-300'}>{invitation.usedAt ? t('members.used') : t('members.pending')}</span></div>{:else}<p class="p-5 text-sm text-slate-500">{t('members.noInvitations')}</p>{/each}</div></section>
		<section class="mt-8 rounded-xl border border-slate-800 bg-slate-900/80"><h2 class="border-b border-slate-800 px-5 py-4 font-semibold text-white">{t('members.audit')}</h2><div class="divide-y divide-slate-800">{#each data.audits as audit}<div class="flex flex-wrap items-center justify-between gap-3 px-5 py-3 text-sm"><div><span class="text-cyan-300">{audit.event}</span><span class="ml-3 text-slate-300">{audit.subject}</span><span class="ml-3 text-slate-500">{audit.actor}</span></div><time class="text-xs text-slate-500" datetime={audit.createdAt}>{formatDateTime(data.locale, audit.createdAt)}</time></div>{:else}<p class="p-5 text-sm text-slate-500">{t('members.noInvitations')}</p>{/each}</div></section>
	</div>
</main>
